mapper.select:
SELECT g.id AS id, g.goods_code AS goodsCode, g.barcode AS barcode, g.name AS name, g.spec AS spec, g.plu_code AS pluCode, u.name AS unitName, g.retail_price AS retailPrice, g.is_weighed AS isWeighed FROM goods g JOIN unit u ON u.id = g.unit_id WHERE g.status = 1
AND g.category_id IN #{cid}
ORDER BY g.id DESC

mapper.update:
UPDATE goods
SET safety_stock_lower = #{lower},
    safety_stock_upper = #{upper},
    update_by          = #{operator}
WHERE id = #{goodsId}

UPDATE goods
SET safety_stock_lower = #{lower},
    safety_stock_upper = #{upper},
    update_by          = #{operator}
WHERE id IN
#{gid}
